import { useState } from "react";
import { useTranslation } from "react-i18next";
import { useLoaderData, useNavigation } from "react-router";

import { NoteForm } from "../components/NoteForm/NoteForm";
import { NoteList } from "../components/NoteList/NoteList";
import { Pulse } from "../components/Pulse/Pulse";
import { newestFirst } from "../shared/notes/notes";
import { clearDraft, writeDraft } from "../shared/storage/draftStorage";
import type { NotesPageData } from "./notesLoader";

export function NotesPage() {
  const { notes, draft } = useLoaderData<NotesPageData>();
  const navigation = useNavigation();
  const { t } = useTranslation();
  const [openId, setOpenId] = useState<string | null>(null);
  if (notes.state === "failed")
    return <p role="alert">{t("page.loadFailed")}</p>;
  const sorted = newestFirst(notes.data);
  const open = sorted.find((note) => note.id === openId);
  const initial =
    open === undefined
      ? (draft ?? { title: "", body: "" })
      : { title: open.title, body: open.body };
  return (
    <main>
      <h1>{t("notes.count", { count: sorted.length })}</h1>
      <Pulse active={navigation.state !== "idle"} />
      <NoteList notes={sorted} onOpen={setOpenId} />
      <NoteForm
        key={openId ?? "draft"}
        initial={initial}
        onSave={(next) =>
          Promise.resolve(writeDraft(next) === "saved" ? "saved" : "failed")
        }
        onDelete={clearDraft}
      />
    </main>
  );
}

