import { useId, useState, type SyntheticEvent } from "react";
import { useTranslation } from "react-i18next";

import type { Draft } from "../../shared/storage/draftStorage";
import { mergeStyleMaps } from "../../shared/styles/mergeStyleMaps";
import own from "./NoteForm.module.scss";
import type { NoteFormClasses, SaveOutcome } from "./types";

type Props = {
  readonly initial: Draft;
  readonly onSave: (draft: Draft) => Promise<SaveOutcome>;
  readonly onDelete: () => void;
  readonly classes?: Partial<NoteFormClasses>;
};

export function NoteForm({ initial, onSave, onDelete, classes }: Props) {
  const { t } = useTranslation();
  const css = mergeStyleMaps<NoteFormClasses>(own, classes);
  const [title, setTitle] = useState(initial.title);
  const [body, setBody] = useState(initial.body);
  const [problem, setProblem] = useState<"titleRequired" | "saveFailed" | null>(
    null,
  );
  const [saving, setSaving] = useState(false);
  const [armed, setArmed] = useState(false);
  const titleId = useId();
  const problemId = useId();

  const submit = async (event: SyntheticEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (title.trim() === "") {
      setProblem("titleRequired");
      return;
    }
    setSaving(true);
    const outcome = await onSave({ title, body });
    setSaving(false);
    setProblem(outcome === "saved" ? null : "saveFailed");
  };

  return (
    <form
      className={css.form}
      aria-busy={saving}
      onSubmit={(event) => void submit(event)}
    >
      <label htmlFor={titleId}>{t("form.title")}</label>
      <input
        id={titleId}
        className={css.field}
        value={title}
        aria-invalid={problem === "titleRequired"}
        aria-describedby={problem === null ? undefined : problemId}
        onChange={(event) => {
          setTitle(event.target.value);
        }}
      />
      <textarea
        className={css.field}
        aria-label={t("form.body")}
        value={body}
        onChange={(event) => {
          setBody(event.target.value);
        }}
      />
      {problem !== null && (
        <p id={problemId} className={css.error} role="alert">
          {t(`form.${problem}`)}
        </p>
      )}
      <div className={css.actions}>
        <button type="submit" disabled={saving}>
          {t("form.save")}
        </button>
        <button
          type="button"
          onClick={() => {
            if (armed) onDelete();
            else setArmed(true);
          }}
        >
          {armed ? t("form.confirmDelete") : t("form.delete")}
        </button>
      </div>
    </form>
  );
}

