import { useEffect, type RefObject } from "react";

const PULSE_PERIOD_MS = 1200;
const PULSE_DEPTH = 0.15;

export const usePulse = (
  target: RefObject<HTMLElement | null>,
  active: boolean,
): void => {
  useEffect(() => {
    const element = target.current;
    if (!active || element === null) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    let frame = 0;
    const step = (time: number) => {
      const phase = (time % PULSE_PERIOD_MS) / PULSE_PERIOD_MS;
      element.style.transform = `scale(${String(1 + PULSE_DEPTH * Math.sin(phase * 2 * Math.PI))})`;
      frame = requestAnimationFrame(step);
    };
    const follow = () => {
      cancelAnimationFrame(frame);
      if (!document.hidden) frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    document.addEventListener("visibilitychange", follow);
    return () => {
      cancelAnimationFrame(frame);
      document.removeEventListener("visibilitychange", follow);
      element.style.transform = "";
    };
  }, [target, active]);
};

