import { z } from "zod";

import type { Note } from "../notes/notes";

const REQUEST_TIMEOUT_MS = 8000;

const NoteDto = z.object({
  note_id: z.string(),
  title: z.string(),
  body: z.string(),
  created_at: z.string(),
});

export type Loaded<T> =
  | { readonly state: "ready"; readonly data: T }
  | { readonly state: "failed"; readonly reason: string };

const toNote = (dto: z.infer<typeof NoteDto>): Note => ({
  id: dto.note_id,
  title: dto.title,
  body: dto.body,
  createdAt: Date.parse(dto.created_at),
});

export const fetchNotes = async (
  baseUrl: string,
  signal: AbortSignal,
): Promise<Loaded<Note[]>> => {
  const response = await fetch(`${baseUrl}/notes`, {
    signal: AbortSignal.any([signal, AbortSignal.timeout(REQUEST_TIMEOUT_MS)]),
  });
  if (!response.ok)
    return {
      state: "failed",
      reason: `notes request failed: ${String(response.status)}`,
    };
  const parsed = z.array(NoteDto).safeParse(await response.json());
  return parsed.success
    ? { state: "ready", data: parsed.data.map(toNote) }
    : { state: "failed", reason: "notes response has an unexpected shape" };
};

