export type LogEntry = {
  readonly level: "info" | "error";
  readonly event: string;
  readonly traceId: string;
  readonly detail: Readonly<Record<string, string | number>>;
};

export type Logger = {
  readonly info: (event: string, detail?: LogEntry["detail"]) => void;
  readonly error: (event: string, detail?: LogEntry["detail"]) => void;
};

export const createLogger = (
  traceId: string,
  sink: (entry: LogEntry) => void,
): Logger => ({
  info: (event, detail = {}) => {
    sink({ level: "info", event, traceId, detail });
  },
  error: (event, detail = {}) => {
    sink({ level: "error", event, traceId, detail });
  },
});

export const consoleSink = (entry: LogEntry): void => {
  if (import.meta.env.PROD) return;
  console.info(JSON.stringify(entry));
};

