import { z } from "zod";

const DRAFT_KEY = "notes-draft";

const DraftV1 = z.object({ version: z.literal(1), text: z.string() });
const DraftV2 = z.object({
  version: z.literal(2),
  title: z.string(),
  body: z.string(),
});

export type Draft = { readonly title: string; readonly body: string };

const fromStored = (raw: unknown): Draft | null => {
  const latest = DraftV2.safeParse(raw);
  if (latest.success)
    return { title: latest.data.title, body: latest.data.body };
  const first = DraftV1.safeParse(raw);
  return first.success ? { title: "", body: first.data.text } : null;
};

const parsed = (text: string): unknown => {
  try {
    return JSON.parse(text);
  } catch (error) {
    if (error instanceof SyntaxError) return null;
    throw error;
  }
};

export const readDraft = (): Draft | null => {
  const text = localStorage.getItem(DRAFT_KEY);
  return text === null ? null : fromStored(parsed(text));
};

export const writeDraft = (draft: Draft): "saved" | "full" => {
  try {
    localStorage.setItem(DRAFT_KEY, JSON.stringify({ version: 2, ...draft }));
    return "saved";
  } catch (error) {
    if (error instanceof DOMException && error.name === "QuotaExceededError")
      return "full";
    throw error;
  }
};

export const clearDraft = (): void => {
  localStorage.removeItem(DRAFT_KEY);
};

