import { afterEach, describe, expect, it, vi } from "vitest";

import { clearDraft, readDraft, writeDraft } from "../draftStorage";

describe("draftStorage", () => {
  afterEach(() => {
    localStorage.clear();
    vi.restoreAllMocks();
  });

  it("keeps a written draft until it is cleared", () => {
    expect(writeDraft({ title: "T", body: "B" })).toBe("saved");
    expect(readDraft()).toEqual({ title: "T", body: "B" });
    clearDraft();
    expect(readDraft()).toBeNull();
  });

  it("reads a draft stored by the first version as body text", () => {
    localStorage.setItem(
      "notes-draft",
      JSON.stringify({ version: 1, text: "old" }),
    );
    expect(readDraft()).toEqual({ title: "", body: "old" });
  });

  it("treats a broken record as no draft", () => {
    localStorage.setItem("notes-draft", "{not json");
    expect(readDraft()).toBeNull();
  });

  it("answers a full storage instead of throwing", () => {
    vi.spyOn(Storage.prototype, "setItem").mockImplementation(() => {
      throw new DOMException("full", "QuotaExceededError");
    });
    expect(writeDraft({ title: "T", body: "B" })).toBe("full");
  });
});
